'use client';

import React, { useState, useEffect } from 'react';
import { Card, Button, Input } from '@/components/ui/base';
import { User, Bell, Shield, CreditCard, Mail, RefreshCw } from 'lucide-react';
import { useTransactions } from "@/lib/transaction-context";

export default function SettingsPage() {
  const [activeTab, setActiveTab] = useState('account');
  const { userProfile, updateUserProfile } = useTransactions();
  const [formData, setFormData] = useState({ name: '', email: '' });

  useEffect(() => {
    if (userProfile) {
      setFormData({
        name: userProfile.name || '',
        email: userProfile.email || ''
      });
    }
  }, [userProfile]);

  const handleUpdateAccount = () => {
    updateUserProfile(formData);
    alert('Account updated successfully!');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-[#111827] text-white p-8 rounded-2xl shadow-lg -mt-4">
        <div>
          <h1 className="text-3xl font-bold mb-2">Settings</h1>
          <p className="text-gray-400">Manage your account settings and set e-mail preferences.</p>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-8">
        {/* Sidebar Navigation */}
        <Card className="w-full md:w-64 p-4 h-fit">
          <nav className="space-y-1">
            <button
              onClick={() => setActiveTab('account')}
              className={`w-full flex items-center gap-3 px-4 py-2 text-sm font-medium rounded-md transition-colors ${
                activeTab === 'account' ? 'bg-gray-100 text-gray-900' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }`}
            >
              <User size={18} /> Account
            </button>
            <button
              onClick={() => setActiveTab('reports')}
              className={`w-full flex items-center gap-3 px-4 py-2 text-sm font-medium rounded-md transition-colors ${
                activeTab === 'reports' ? 'bg-gray-100 text-gray-900' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }`}
            >
              <Mail size={18} /> Reports
            </button>
            <button
              onClick={() => setActiveTab('appearance')}
              className={`w-full flex items-center gap-3 px-4 py-2 text-sm font-medium rounded-md transition-colors ${
                activeTab === 'appearance' ? 'bg-gray-100 text-gray-900' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }`}
            >
              <Shield size={18} /> Security
            </button>
            <button
              onClick={() => setActiveTab('billing')}
              className={`w-full flex items-center gap-3 px-4 py-2 text-sm font-medium rounded-md transition-colors ${
                activeTab === 'billing' ? 'bg-gray-100 text-gray-900' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }`}
            >
              <CreditCard size={18} /> Billing
            </button>
          </nav>
        </Card>

        {/* Content Area */}
        <div className="flex-1">
          {activeTab === 'account' && (
            <Card className="p-8">
              <div className="mb-8">
                <h2 className="text-xl font-bold text-gray-900">Account</h2>
                <p className="text-sm text-gray-500">Update your account settings.</p>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Profile Picture</label>
                  <div className="flex items-center gap-4">
                    <div className="h-16 w-16 rounded-full bg-green-500 flex items-center justify-center text-white text-xl font-bold">
                      {formData.name ? formData.name.substring(0, 2).toUpperCase() : 'ME'}
                    </div>
                    <div className="flex items-center gap-2 border border-gray-300 rounded-md px-3 py-2 bg-white">
                      <Button variant="ghost" size="sm">Choose File</Button>
                      <span className="text-sm text-gray-500">No file chosen</span>
                    </div>
                  </div>
                  <p className="mt-2 text-xs text-gray-500">Recommended: Square JPG, PNG, at least 300x300px.</p>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Name</label>
                  <Input 
                    value={formData.name} 
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    placeholder="Your Name" 
                    className="max-w-md" 
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
                  <Input 
                    value={formData.email} 
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                    placeholder="your.email@example.com" 
                    className="max-w-md" 
                    type="email"
                  />
                  <p className="text-xs text-gray-500 mt-1">This email will be used for sending reports.</p>
                </div>

                <div>
                  <Button 
                    variant="primary" 
                    className="bg-green-500 hover:bg-green-600"
                    onClick={handleUpdateAccount}
                  >
                    Update account
                  </Button>
                </div>
              </div>
            </Card>
          )}

          {activeTab === 'reports' && (
            <div className="space-y-6">
              <div className="flex justify-between items-start">
                <Card className="flex-1 p-6 mr-6">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">Report History</h3>
                  <div className="overflow-hidden">
                    <table className="min-w-full divide-y divide-gray-200">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Report Period</th>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Sent Date</th>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="bg-white divide-y divide-gray-200">
                        <tr>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">May 1-31, 2025</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">5/24/2025</td>
                          <td className="px-6 py-4 whitespace-nowrap"><span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">SENT</span></td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            <button className="flex items-center gap-1 text-gray-600 hover:text-gray-900"><RefreshCw size={14}/> Resend</button>
                          </td>
                        </tr>
                        <tr>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">April 1-30, 2025</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">5/24/2025</td>
                          <td className="px-6 py-4 whitespace-nowrap"><span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">SENT</span></td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            <button className="flex items-center gap-1 text-gray-600 hover:text-gray-900"><RefreshCw size={14}/> Resend</button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </Card>

                <Card className="w-80 p-6 h-fit">
                  <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-gray-900">Report Settings</h3>
                    <button className="text-gray-400 hover:text-gray-600"><X size={20} /></button>
                  </div>
                  <p className="text-sm text-gray-500 mb-6">Enable or disable monthly financial report emails</p>
                  
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-medium text-sm">Monthly Reports</p>
                        <p className="text-xs text-gray-500">Reports deactivated</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" className="sr-only peer" />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-green-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-600"></div>
                      </label>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
                      <div className="flex items-center gap-2 text-gray-500 text-sm">
                        <Mail size={16} />
                        <span>affiliatebusinessprog@gmail.com</span>
                      </div>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Repeat On</label>
                      <p className="text-sm text-gray-400">Monthly</p>
                    </div>

                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="font-medium text-sm mb-1">Schedule Summary</p>
                      <p className="text-xs text-gray-500">Reports are currently deactivated</p>
                    </div>

                    <Button className="w-full bg-green-500 hover:bg-green-600 text-white">
                      Save changes
                    </Button>
                  </div>
                </Card>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function X({ size }: { size: number }) {
  return (
    <svg 
      xmlns="http://www.w3.org/2000/svg" 
      width={size} 
      height={size} 
      viewBox="0 0 24 24" 
      fill="none" 
      stroke="currentColor" 
      strokeWidth="2" 
      strokeLinecap="round" 
      strokeLinejoin="round"
    >
      <line x1="18" y1="6" x2="6" y2="18"></line>
      <line x1="6" y1="6" x2="18" y2="18"></line>
    </svg>
  )
}
